USE god2_game;

CREATE TABLE IF NOT EXISTS god2_research.xjz_quest_reward_capture_targets (
    source_target_id INT NOT NULL,
    client_quest_id INT NOT NULL,
    quest_code VARCHAR(128) NULL,
    quest_type VARCHAR(64) NOT NULL,
    branch_id INT NOT NULL,
    quest_name_zh_tw VARCHAR(200) NOT NULL,
    formal_quest_id BIGINT NULL,
    formal_quest_code VARCHAR(100) NULL,
    formal_quest_name_zh_tw VARCHAR(200) NULL,
    min_rebirth INT NULL,
    max_rebirth INT NULL,
    min_level INT NULL,
    step_count INT NOT NULL,
    requirement_count INT NOT NULL,
    reward_materialization_status VARCHAR(96) NOT NULL,
    runtime_use_status VARCHAR(96) NOT NULL,
    capture_priority VARCHAR(32) NOT NULL,
    capture_context VARCHAR(96) NOT NULL,
    wanted_fields_json TEXT NOT NULL,
    target_reward_table VARCHAR(64) NOT NULL,
    sample_table VARCHAR(64) NOT NULL,
    request_hint_zh_tw VARCHAR(512) NOT NULL,
    current_client_source VARCHAR(128) NOT NULL,
    raw_source VARCHAR(256) NOT NULL,
    raw_line INT NULL,
    evidence_status VARCHAR(64) NOT NULL,
    packet_evidence_boundary TINYINT(1) NOT NULL,
    source_pack_id VARCHAR(96) NOT NULL,
    promoted_to_formal_reward TINYINT(1) NOT NULL DEFAULT 0,
    blocked_reason_zh_tw VARCHAR(512) NOT NULL,
    created_at_utc DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),
    PRIMARY KEY (source_pack_id, source_target_id),
    KEY idx_xjz_quest_reward_target_client_quest (client_quest_id),
    KEY idx_xjz_quest_reward_target_formal_quest (formal_quest_id),
    KEY idx_xjz_quest_reward_target_priority (capture_priority)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS god2_research.xjz_quest_reward_capture_target_summary (
    source_pack_id VARCHAR(96) NOT NULL,
    quest_type VARCHAR(64) NOT NULL,
    capture_priority VARCHAR(32) NOT NULL,
    target_count INT NOT NULL,
    linked_formal_quest_count INT NOT NULL,
    total_step_count INT NOT NULL,
    total_requirement_count INT NOT NULL,
    blocked_reason_zh_tw VARCHAR(512) NOT NULL,
    PRIMARY KEY (source_pack_id, quest_type, capture_priority)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TEMPORARY TABLE xjz_quest_reward_capture_target_stage (
    target_id INT NOT NULL PRIMARY KEY,
    quest_id INT NOT NULL,
    quest_code VARCHAR(128) NULL,
    quest_type VARCHAR(64) NOT NULL,
    branch_id INT NOT NULL,
    name_zh_tw VARCHAR(200) NOT NULL,
    min_rebirth INT NULL,
    max_rebirth INT NULL,
    min_level INT NULL,
    step_count INT NOT NULL,
    requirement_count INT NOT NULL,
    reward_materialization_status VARCHAR(96) NOT NULL,
    runtime_use_status VARCHAR(96) NOT NULL,
    capture_priority VARCHAR(32) NOT NULL,
    capture_context VARCHAR(96) NOT NULL,
    wanted_fields_json TEXT NOT NULL,
    target_reward_table VARCHAR(64) NOT NULL,
    sample_table VARCHAR(64) NOT NULL,
    request_hint_zh_tw VARCHAR(512) NOT NULL,
    current_client_source VARCHAR(128) NOT NULL,
    raw_source VARCHAR(256) NOT NULL,
    raw_line INT NULL,
    evidence_status VARCHAR(64) NOT NULL,
    packet_evidence_boundary INT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DELETE FROM god2_research.xjz_quest_reward_capture_targets
WHERE source_pack_id = 'XJZ-csharp-evidence-capture-pack-20260818';

    source_target_id,
    client_quest_id,
    quest_code,
    quest_type,
    branch_id,
    quest_name_zh_tw,
    formal_quest_id,
    formal_quest_code,
    formal_quest_name_zh_tw,
    min_rebirth,
    max_rebirth,
    min_level,
    step_count,
    requirement_count,
    reward_materialization_status,
    runtime_use_status,
    capture_priority,
    capture_context,
    wanted_fields_json,
    target_reward_table,
    sample_table,
    request_hint_zh_tw,
    current_client_source,
    raw_source,
    raw_line,
    evidence_status,
    packet_evidence_boundary,
    source_pack_id,
    promoted_to_formal_reward,
    blocked_reason_zh_tw
)
SELECT
    s.target_id,
    s.quest_id,
    s.quest_code,
    s.quest_type,
    s.branch_id,
    s.name_zh_tw,
    q.quest_id,
    q.code,
    q.name_zh_tw,
    s.min_rebirth,
    s.max_rebirth,
    s.min_level,
    s.step_count,
    s.requirement_count,
    s.reward_materialization_status,
    s.runtime_use_status,
    s.capture_priority,
    s.capture_context,
    s.wanted_fields_json,
    s.target_reward_table,
    s.sample_table,
    s.request_hint_zh_tw,
    s.current_client_source,
    s.raw_source,
    s.raw_line,
    s.evidence_status,
    s.packet_evidence_boundary,
    'XJZ-csharp-evidence-capture-pack-20260818',
    0,
    '目前只有任務獎勵抓包目標，沒有 reward claim sample；正式 quest_rewards 不硬填。'
FROM xjz_quest_reward_capture_target_stage s
LEFT JOIN god2_game.quests q
    ON q.quest_id = s.quest_id;

DELETE FROM god2_research.xjz_quest_reward_capture_target_summary
WHERE source_pack_id = 'XJZ-csharp-evidence-capture-pack-20260818';

    source_pack_id,
    quest_type,
    capture_priority,
    target_count,
    linked_formal_quest_count,
    total_step_count,
    total_requirement_count,
    blocked_reason_zh_tw
)
SELECT
    'XJZ-csharp-evidence-capture-pack-20260818',
    quest_type,
    capture_priority,
    COUNT(*) AS target_count,
    COUNT(formal_quest_id) AS linked_formal_quest_count,
    SUM(step_count) AS total_step_count,
    SUM(requirement_count) AS total_requirement_count,
    '需要實際完成任務並抓取獎勵領取封包與前後狀態，才能升正式獎勵表。'
FROM god2_research.xjz_quest_reward_capture_targets
WHERE source_pack_id = 'XJZ-csharp-evidence-capture-pack-20260818'
GROUP BY quest_type, capture_priority;

UPDATE god2_research.xjz_csharp_apply_queue
SET
    safe_apply_level_zh_tw = CONCAT(
        '已匯入任務獎勵抓包目標 ',
        (SELECT COUNT(*) FROM god2_research.xjz_quest_reward_capture_targets WHERE source_pack_id = 'XJZ-csharp-evidence-capture-pack-20260818'),
        ' 筆，已對到正式任務 ',
        (SELECT COUNT(*) FROM god2_research.xjz_quest_reward_capture_targets WHERE source_pack_id = 'XJZ-csharp-evidence-capture-pack-20260818' AND formal_quest_id IS NOT NULL),
        ' 筆'
    ),
    next_server_action_zh_tw = '任務獎勵抓包清單已建立；正式獎勵內容需 reward claim sample，不得用目標清單硬填。'
WHERE queue_key = 'quest_reward_targets';
